# [cfg_attr (not (doctest) , doc = " IOTA System State Type Upgrade Guide")] # [cfg_attr (not (doctest) , doc = " `IotaSystemState` is a thin wrapper around `IotaSystemStateV1` that provides a versioned interface.")] # [cfg_attr (not (doctest) , doc = " The `IotaSystemState` object has a fixed ID 0x5, and the `IotaSystemStateV1` object is stored as a dynamic field.")] # [cfg_attr (not (doctest) , doc = " There are a few different ways to upgrade the `IotaSystemStateV1` type:")] # [cfg_attr (not (doctest) , doc = "")] # [cfg_attr (not (doctest) , doc = " The simplest and one that doesn't involve a real upgrade is to just add dynamic fields to the `extra_fields` field")] # [cfg_attr (not (doctest) , doc = " of `IotaSystemStateV1` or any of its sub type. This is useful when we are in a rush, or making a small change,")] # [cfg_attr (not (doctest) , doc = " or still experimenting a new field.")] # [cfg_attr (not (doctest) , doc = "")] # [cfg_attr (not (doctest) , doc = " To properly upgrade the `IotaSystemStateV1` type, we need to ship a new framework that does the following:")] # [cfg_attr (not (doctest) , doc = " 1. Define a new `IotaSystemState`type (e.g. `IotaSystemStateV2`).")] # [cfg_attr (not (doctest) , doc = " 2. Define a data migration function that migrates the old (e.g. `IotaSystemStateV1`) to the new one (e.g. `IotaSystemStateV2`).")] # [cfg_attr (not (doctest) , doc = " 3. Replace all uses of `IotaSystemStateV1` with `IotaSystemStateV2` in both iota_system.move and iota_system_state_inner.move,")] # [cfg_attr (not (doctest) , doc = "    with the exception of the `iota_system_state_inner::create` function, which should always return the genesis type.")] # [cfg_attr (not (doctest) , doc = " 4. Inside `load_inner_maybe_upgrade` function, check the current version in the wrapper, and if it's not the latest version,")] # [cfg_attr (not (doctest) , doc = "   call the data migration function to upgrade the inner object. Make sure to also update the version in the wrapper.")] # [cfg_attr (not (doctest) , doc = " A detailed example can be found in iota/tests/framework_upgrades/mock_iota_systems/shallow_upgrade.")] # [cfg_attr (not (doctest) , doc = " Along with the Move change, we also need to update the Rust code to support the new type. This includes:")] # [cfg_attr (not (doctest) , doc = " 1. Define a new `IotaSystemState` struct type that matches the new Move type, and implement the `IotaSystemStateTrait`.")] # [cfg_attr (not (doctest) , doc = " 2. Update the `IotaSystemState` struct to include the new version as a new enum variant.")] # [cfg_attr (not (doctest) , doc = " 3. Update the `get_iota_system_state` function to handle the new version.")] # [cfg_attr (not (doctest) , doc = " To test that the upgrade will be successful, we need to modify `iota_system_state_production_upgrade_test` test in")] # [cfg_attr (not (doctest) , doc = " protocol_version_tests and trigger a real upgrade using the new framework. We will need to keep this directory as old version,")] # [cfg_attr (not (doctest) , doc = " put the new framework in a new directory, and run the test to exercise the upgrade.")] # [cfg_attr (not (doctest) , doc = "")] # [cfg_attr (not (doctest) , doc = " To upgrade Validator type, besides everything above, we also need to:")] # [cfg_attr (not (doctest) , doc = " 1. Define a new Validator type (e.g. ValidatorV2).")] # [cfg_attr (not (doctest) , doc = " 2. Define a data migration function that migrates the old ValidatorV1 to the new one (i.e. ValidatorV2).")] # [cfg_attr (not (doctest) , doc = " 3. Replace all uses of ValidatorV1 with ValidatorV2 except the genesis creation function.")] # [cfg_attr (not (doctest) , doc = " 4. In validator_wrapper::upgrade_to_latest, check the current version in the wrapper, and if it's not the latest version,")] # [cfg_attr (not (doctest) , doc = "  call the data migration function to upgrade it.")] # [cfg_attr (not (doctest) , doc = " In Rust, we also need to add a new case in `get_validator_from_table`.")] # [cfg_attr (not (doctest) , doc = " Note that it is possible to upgrade IotaSystemStateV1 without upgrading ValidatorV1, but not the other way around.")] # [cfg_attr (not (doctest) , doc = " And when we only upgrade IotaSystemStateV1, the version of ValidatorV1 in the wrapper will not be updated, and hence may become")] # [cfg_attr (not (doctest) , doc = " inconsistent with the version of IotaSystemStateV1. This is fine as long as we don't use the ValidatorV1 version to determine")] # [cfg_attr (not (doctest) , doc = " the IotaSystemStateV1 version, or vice versa.")] # [allow (rustdoc :: all)] pub mod iota_system { # [allow (non_camel_case_types , unused)] type address = :: moverox :: types :: Address ; # [allow (non_camel_case_types , unused)] type u256 = :: moverox :: types :: U256 ; # [allow (non_camel_case_types , unused)] type vector < T > = :: std :: vec :: Vec < T > ; # [derive (Clone , Debug , PartialEq , Eq , Hash , :: moverox :: traits :: MoveDatatype , :: moverox :: serde :: Deserialize , :: moverox :: serde :: Serialize ,)] # [move_ (crate = :: moverox :: traits)] # [serde (crate = "::moverox::serde")] # [move_ (address = "0x3")] # [move_ (module = iota_system)] # [allow (non_snake_case)] pub struct IotaSystemState { pub id : crate :: iota_framework :: object :: UID , pub version : u64 } impl IotaSystemState { # [allow (clippy :: just_underscores_and_digits , clippy :: too_many_arguments)] pub const fn new (id : crate :: iota_framework :: object :: UID , version : u64) -> Self { Self { id , version , } } } impl :: moverox :: traits :: HasKey for IotaSystemState { fn address (& self) -> :: moverox :: types :: Address { self . id . id . bytes } } }
